param([ValidateSet('native','download','install')][string]$Mode='native',[string]$Id='')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12
$root=Join-Path $env:LOCALAPPDATA 'YouTubeAudioBridge';$jobs=Join-Path $root 'jobs';$bin=Join-Path $root 'yt-dlp.exe';[IO.Directory]::CreateDirectory($jobs)|Out-Null
function JobPath($id){if($id -notmatch '^[0-9a-f]{32}$'){throw 'Invalid job ID'};Join-Path $jobs "$id.json"}
function ReadJob($id){Get-Content -Raw -LiteralPath (JobPath $id) -Encoding UTF8|ConvertFrom-Json}
function WriteJson($path,$obj){$temp="$path.$PID.tmp";[IO.File]::WriteAllText($temp,($obj|ConvertTo-Json -Depth 12 -Compress),[Text.UTF8Encoding]::new($false));Move-Item -LiteralPath $temp -Destination $path -Force}
function WriteJob($j){WriteJson (JobPath $j.id) $j}
function Launch($mode,$id){$script=$PSCommandPath;$args=@('-NoLogo','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',('"'+$script+'"'),'-Mode',$mode);if($id){$args+=@('-Id',$id)};Start-Process -FilePath "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -ArgumentList $args -WindowStyle Hidden|Out-Null}
function Normalize($raw){if(!$raw -or $raw.Length -gt 4096){throw 'Invalid URL'};try{$u=[uri]$raw}catch{throw 'Invalid URL'};if($u.Scheme -notin @('http','https') -or $u.UserInfo -or !$u.IsDefaultPort -or $u.IsLoopback -or $u.Host -notmatch '\.' -or $u.Host -match '^(localhost|127\.|10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2[0-9]|3[01])\.)'){throw 'Use a public HTTP(S) media URL without credentials'};if($u.Host -in @('youtube.com','www.youtube.com','m.youtube.com','music.youtube.com','youtu.be')){$vid='';if($u.Host -eq 'youtu.be'){$vid=$u.AbsolutePath.Trim('/')}elseif($u.AbsolutePath -match '^/(shorts|live)/([A-Za-z0-9_-]{11})'){$vid=$Matches[2]}elseif($u.Query -match '(?:^|[?&])v=([A-Za-z0-9_-]{11})(?:&|$)'){$vid=$Matches[1]};if($vid -match '^[A-Za-z0-9_-]{11}$'){return "https://www.youtube.com/watch?v=$vid"}};return $u.AbsoluteUri}
function InspectMedia($url){$raw=& $bin --ignore-config --no-js-runtimes --no-remote-components --no-cookies --no-playlist --skip-download --no-warnings --socket-timeout 20 -J -- $url 2>$null;if($LASTEXITCODE -ne 0){throw 'Site unavailable, unsupported or requires access / JS runtime'};$meta=($raw -join "
")|ConvertFrom-Json;$formats=@($meta.formats|Where-Object {!$_.has_drm -and $_.format_id -match '^[A-Za-z0-9_.-]+$'});$audio=$formats|Where-Object {$_.vcodec -eq 'none' -and $_.acodec -ne 'none' -and $_.ext -eq 'm4a'}|Sort-Object abr -Descending|Select-Object -First 1;$choices=@();foreach($height in @(360,480,720,1080,1440,2160)){$combined=$formats|Where-Object {$_.ext -eq 'mp4' -and $_.height -eq $height -and $_.vcodec -ne 'none' -and $_.acodec -and $_.acodec -ne 'none'}|Sort-Object tbr -Descending|Select-Object -First 1;if($combined){$choices+=@{height=$height;selection=$combined.format_id;merged=$true;size=$combined.filesize}}else{$video=$formats|Where-Object {$_.ext -eq 'mp4' -and $_.height -eq $height -and $_.vcodec -match '^(avc1|av01)'  -and $_.acodec -eq 'none'}|Sort-Object tbr -Descending|Select-Object -First 1;if($video -and $audio){$choices+=@{height=$height;selection=($video.format_id+'+'+$audio.format_id);merged=$false;size=$(if($video.filesize -and $audio.filesize){$video.filesize+$audio.filesize}else{0})}}}};if(!$choices.Count -and $meta.ext -eq 'mp4' -and !$meta.has_drm -and $meta.format_id -match '^[A-Za-z0-9_.-]+$'){$choices+=@{height=0;selection=$meta.format_id;merged=$true;verify=$true;size=$meta.filesize}};return @{title=$meta.title;duration=$meta.duration;thumbnail=$meta.thumbnail;choices=$choices}}
function DownloadYt(){try{WriteJson (Join-Path $root 'install.json') @{status='installing';message='Downloading yt-dlp'};$base='https://github.com/yt-dlp/yt-dlp/releases/latest/download';$temp=Join-Path $root 'yt-dlp.new.exe';$hashes=Join-Path $root 'SHA2-256SUMS.tmp';Invoke-WebRequest -UseBasicParsing -Uri "$base/SHA2-256SUMS" -OutFile $hashes;Invoke-WebRequest -UseBasicParsing -Uri "$base/yt-dlp.exe" -OutFile $temp;$entry=Get-Content -LiteralPath $hashes|Where-Object {$_ -match '^([a-fA-F0-9]{64})\s+\*?yt-dlp\.exe$'}|Select-Object -First 1;if(!$entry){throw 'Official checksum is missing'};$expected=($entry -split '\s+')[0];if((Get-FileHash -LiteralPath $temp -Algorithm SHA256).Hash -ne $expected){throw 'yt-dlp checksum mismatch'};& $temp --version | Out-Null;if($LASTEXITCODE -ne 0){throw 'yt-dlp version check failed'};Move-Item -LiteralPath $temp -Destination $bin -Force;Remove-Item -LiteralPath $hashes -Force;WriteJson (Join-Path $root 'install.json') @{status='ready';message='yt-dlp installed and verified'}}catch{if($temp){Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue};if($hashes){Remove-Item -LiteralPath $hashes -Force -ErrorAction SilentlyContinue};WriteJson (Join-Path $root 'install.json') @{status='error';message=$_.Exception.Message}}}
function RunDownload($id){$j=ReadJob $id;$dir=Join-Path $jobs $id;[IO.Directory]::CreateDirectory($dir)|Out-Null;$selector='bestaudio';if($j.quality -in @('128','192','320')){$selector='bestaudio/best'};$template='audio.%(ext)s';if($j.quality -eq 'mp4'){$selector=$j.selection.Replace('+',',');$template='audio.%(format_id)s.%(ext)s'}elseif($j.quality -eq 'original-video'){$selector='best[vcodec!=none][acodec!=none]/bestvideo';$template='audio.%(ext)s'};$out=Join-Path $dir $template;$stdout=Join-Path $dir 'stdout.log';$stderr=Join-Path $dir 'stderr.log';$j.status='running';$j.workerPid=$PID;WriteJob $j;try{$args=@('--ignore-config','--no-js-runtimes','--no-remote-components','--no-cookies','--no-cache-dir','--no-playlist','--no-warnings','--no-overwrites','--hls-prefer-native','--write-info-json','--fixup','never','--newline','--retries','3','--socket-timeout','20','-f',$selector,'--progress-template','"download:PROGRESS:%(progress._percent_str)s"','-o',('"'+$out+'"'),'--',$j.url);$p=Start-Process -FilePath $bin -ArgumentList $args -WindowStyle Hidden -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru;$null=$p.Handle;while(!$p.HasExited){Start-Sleep -Milliseconds 750;if(Test-Path -LiteralPath (Join-Path $dir 'cancel')){try{if(!$p.HasExited){$p.Kill()}}catch{};$p.WaitForExit();$j.status='cancelled';$j.message='Cancelled';WriteJob $j;return};if(Test-Path $stdout){$line=Get-Content -LiteralPath $stdout -Tail 5 -ErrorAction SilentlyContinue|Where-Object {$_ -match 'PROGRESS:\s*([\d.]+)%'}|Select-Object -Last 1;if($line -and $line -match 'PROGRESS:\s*([\d.]+)%'){$j.percent=[double]::Parse($Matches[1],[Globalization.CultureInfo]::InvariantCulture);WriteJob $j}};$p.Refresh()};$p.WaitForExit();if($p.ExitCode -ne 0){$err=(Get-Content -LiteralPath $stderr -Tail 3 -ErrorAction SilentlyContinue)-join ' ';throw $(if($err){$err}else{'yt-dlp failed'})};$files=@(Get-ChildItem -LiteralPath $dir -File|Where-Object {$_.Name -match '^audio(?:\.[A-Za-z0-9_-]+)?\.(webm|m4a|mp4|opus|ogg|mp3|aac|flv|mkv|mov|wav)$'});if($j.quality -eq 'mp4' -and $j.selection -like '*+*'){$ids=$j.selection.Split('+');$main=$files|Where-Object {$_.Name -like ('audio.'+$ids[0]+'.*')}|Select-Object -First 1;$second=$files|Where-Object {$_.Name -like ('audio.'+$ids[1]+'.*')}|Select-Object -First 1;if(!$main -or !$second){throw 'Both video and audio streams are required'};$j.secondFile=$second.Name;$j.secondSize=$second.Length;$files=@($main)};if($files.Count -ne 1){throw 'No unique media file was produced'};$info=Get-ChildItem -LiteralPath $dir -Filter '*.info.json'|Select-Object -First 1 -ExpandProperty FullName;if($info -and (Test-Path -LiteralPath $info)){try{$meta=Get-Content -LiteralPath $info -Raw -Encoding UTF8|ConvertFrom-Json;$j.title=[string]$meta.title;$j.author=[string]$meta.uploader;$j.silent=($meta.acodec -eq 'none')}catch{};Remove-Item -LiteralPath $info -Force -ErrorAction SilentlyContinue};$j.status='ready';$j.file=$files[0].Name;$j.size=$files[0].Length;$j.percent=100;$j.message='Audio ready for browser export';WriteJob $j}catch{$j.status='error';$j.message=$_.Exception.Message;WriteJob $j}finally{Remove-Item -LiteralPath $stdout,$stderr -Force -ErrorAction SilentlyContinue;if($j.status -in @('cancelled','error')){Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue|Remove-Item -Force -ErrorAction SilentlyContinue}}}
function Command($m){switch($m.action){'status' {$version='';if(Test-Path -LiteralPath $bin){$version=(& $bin --version 2>$null|Select-Object -First 1)};$inst=Join-Path $root 'install.json';return @{installed=[bool]$version;version=$version;installation=$(if(Test-Path $inst){Get-Content -Raw $inst|ConvertFrom-Json}else{$null})}}
'inspect' {if(!(Test-Path -LiteralPath $bin)){throw 'Install yt-dlp first'};return InspectMedia (Normalize $m.url)}
'install' {if(Test-Path (Join-Path $root 'install.json')){try{if((Get-Content -Raw (Join-Path $root 'install.json')|ConvertFrom-Json).status -eq 'installing'){return @{ok=$true}}}catch{}};WriteJson (Join-Path $root 'install.json') @{status='installing';message='Preparing'};Launch 'install' '';return @{ok=$true}}
'add' {if(!(Test-Path -LiteralPath $bin)){throw 'yt-dlp is not installed'};if($m.quality -notin @('original','128','192','320','mp4','original-video')){throw 'Invalid format'};$url=Normalize $m.url;if($m.quality -eq 'mp4'){$available=InspectMedia $url;$chosen=$available.choices|Where-Object {$_.selection -eq $m.selection}|Select-Object -First 1;if(!$chosen){throw 'Selected MP4 streams are unavailable'};if(!$chosen.merged -and $chosen.size -gt 67108864){throw 'Separate streams exceed browser memory limit; choose a lower ready MP4 or Original Video'}};if($m.quality -eq 'mp4' -and $m.selection -notmatch '^[A-Za-z0-9_.-]+(\+[A-Za-z0-9_.-]+)?$'){throw 'Analyze media and select an available MP4 resolution first'};foreach($f in Get-ChildItem $jobs -Filter '*.json' -File){try{$x=Get-Content -Raw $f.FullName|ConvertFrom-Json;if($x.url -eq $url -and $x.status -in @('queued','running','ready','exporting')){throw 'This video is already in the queue'}}catch{if($_.Exception.Message -like '*already in the queue*'){throw}}};$id=[guid]::NewGuid().ToString('N');$j=@{id=$id;url=$url;quality=$m.quality;selection=$m.selection;verifyVideo=($m.quality -eq 'mp4' -and [bool]$chosen.verify);secondFile='';secondSize=0;silent=$false;status='queued';file='';size=0;title='';author='';workerPid=0;created=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();message='Queued';percent=0};WriteJob $j;Launch 'download' $id;return @{job=$j}}
'list' {$all=@(Get-ChildItem $jobs -Filter '*.json' -File|Sort-Object LastWriteTime -Descending|Select-Object -First 30|ForEach-Object {try{Get-Content -Raw -LiteralPath $_.FullName|ConvertFrom-Json}catch{}});$active=$false;foreach($x in $all){if($x.status -eq 'running'){if($x.workerPid -and (Get-Process -Id $x.workerPid -ErrorAction SilentlyContinue)){$active=$true}else{$x.status='error';$x.message='Download interrupted. Retry the job.';WriteJob $x}}};if(!$active){$waiting=$all|Where-Object {$_.status -eq 'queued'}|Select-Object -First 1;if($waiting){Launch 'download' $waiting.id}};return @{jobs=$all}}
'cancel' {$j=ReadJob $m.id;if($j.status -in @('queued','running')){$d=Join-Path $jobs $j.id;[IO.Directory]::CreateDirectory($d)|Out-Null;[IO.File]::WriteAllText((Join-Path $d 'cancel'),'');if($j.status -eq 'queued'){$j.status='cancelled';$j.message='Cancelled';WriteJob $j}};return @{ok=$true}}
'read' {$j=ReadJob $m.id;if($j.status -ne 'ready'){throw 'Audio is not ready'};if($j.file -notmatch '^audio(?:\.[A-Za-z0-9_-]+)?\.(webm|m4a|mp4|opus|ogg|mp3|aac|flv|mkv|mov|wav)$'){throw 'Invalid stored file'};$readFile=$j.file;$readSize=$j.size;if($m.slot -eq 'audio'){$readFile=$j.secondFile;$readSize=$j.secondSize;if(!$readFile -or $readFile -notmatch '^audio\.[A-Za-z0-9_-]+\.(m4a|webm|aac|opus)$'){throw 'No valid audio stream'}};$offset=[long]$m.offset;if($offset -lt 0 -or $offset -gt [long]$readSize){throw 'Invalid offset'};$path=Join-Path (Join-Path $jobs $j.id) $readFile;$stream=[IO.File]::OpenRead($path);try{$stream.Position=$offset;$buffer=New-Object byte[] 524288;$n=$stream.Read($buffer,0,$buffer.Length);return @{data=[Convert]::ToBase64String($buffer,0,$n);bytes=$n;size=$readSize;file=$readFile}}finally{$stream.Dispose()}}
'export-error' {$j=ReadJob $m.id;if($j.status -ne 'ready'){throw 'Job is not ready'};$j.status='error';$j.message=([string]$m.message).Substring(0,[Math]::Min(400,([string]$m.message).Length));WriteJob $j;return @{ok=$true}}
'cleanup' {$j=ReadJob $m.id;if($j.status -ne 'ready'){throw 'Job is not ready'};$d=Join-Path $jobs $j.id;if(Test-Path -LiteralPath $d){Remove-Item -LiteralPath $d -Recurse -Force};$j.status='done';$j.message='Saved';WriteJob $j;return @{ok=$true}}
default {throw 'Unknown command'}}}
if($Mode -eq 'install'){DownloadYt;exit};if($Mode -eq 'download'){
 $mutex=New-Object Threading.Mutex($false,'Local\YouTubeAudioBridgeQueue');$owns=$false;try{try{$owns=$mutex.WaitOne(0)}catch [Threading.AbandonedMutexException]{$owns=$true};if(!$owns){exit};while($true){$next=Get-ChildItem $jobs -Filter '*.json' -File|Sort-Object LastWriteTime|ForEach-Object {try{Get-Content -Raw -LiteralPath $_.FullName|ConvertFrom-Json}catch{}}|Where-Object {$_.status -eq 'queued'}|Select-Object -First 1;if(!$next){break};RunDownload $next.id}}finally{if($owns){$mutex.ReleaseMutex()};$mutex.Dispose()};$remaining=Get-ChildItem $jobs -Filter '*.json' -File|ForEach-Object {try{Get-Content -Raw -LiteralPath $_.FullName|ConvertFrom-Json}catch{}}|Where-Object {$_.status -eq 'queued'}|Select-Object -First 1;if($remaining){Launch 'download' $remaining.id};exit}
$inputStream=[Console]::OpenStandardInput();$outputStream=[Console]::OpenStandardOutput();while($true){$head=New-Object byte[] 4;$n=$inputStream.Read($head,0,4);if($n -eq 0){break};while($n -lt 4){$q=$inputStream.Read($head,$n,4-$n);if(!$q){exit};$n+=$q};$length=[BitConverter]::ToInt32($head,0);if($length -lt 2 -or $length -gt 1048576){exit};$payload=New-Object byte[] $length;$n=0;while($n -lt $length){$q=$inputStream.Read($payload,$n,$length-$n);if(!$q){exit};$n+=$q};try{$m=[Text.Encoding]::UTF8.GetString($payload)|ConvertFrom-Json;$r=Command $m}catch{$r=@{error=$_.Exception.Message}};$data=[Text.Encoding]::UTF8.GetBytes(($r|ConvertTo-Json -Depth 12 -Compress));$header=[BitConverter]::GetBytes([int]$data.Length);$outputStream.Write($header,0,4);$outputStream.Write($data,0,$data.Length);$outputStream.Flush()}
